/bin/bash -lc "PORT=0 DB_PATH=data/launch-check.sqlite node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { rm } from 'node:fs/promises';
const child = spawn('npm', ['start'], { env: process.env, stdio: ['ignore', 'pipe', 'inherit'] });
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.stdout.on('data', data => {
      const match = /listening on port (\\d+)/.exec(String(data));
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start and /health verified');
} finally {
  const stopped = once(child, 'exit');
  child.kill('SIGTERM');
  await stopped;
  await rm('data/launch-check.sqlite', { force: true });
}
EOF"

